// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  random,
} from '../remotionShim';


export type CinematicShadowsProps = Record<string, any>;

const CinematicShadows: React.FC<CinematicShadowsProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  solidBackgroundColor = "#1E1E24",
  shadowColor = "#020202",
  moneyColor = "#4ADE80",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for background
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Cinematic slow camera push
  const cinematicScale = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [1, 1.08],
    { extrapolateRight: "clamp" }
  );

  // Layout calculations optimized for 16:9
  // Basing size primarily on height ensures they fill the vertical space naturally in landscape
  const figureHeight = height * 0.65;
  const figureWidth = figureHeight * (150 / 200); // based on SVG viewBox 150x200

  // Placed slightly off-screen to frame the horizontal expanse gracefully
  const giverX = -width * 0.02;
  const receiverX = width * 1.02 - figureWidth;

  // Grounded slightly lower to fit the wider aspect ratio perfectly
  const bottomOffset = height * 0.08;
  const handYFromBottom = figureHeight * (90 / 200); // Hand is roughly 90 units from the bottom in 200 viewBox
  const moneyBaseBottom = bottomOffset + handYFromBottom;

  const moneyWidth = figureWidth * 0.22;
  const moneyHeight = moneyWidth * 0.5;

  // The hand coordinates relative to the screen
  // Giver arm extends to x=145 in viewBox. Receiver arm is flipped so it extends to the left.
  const moneyStartX = giverX + figureWidth * (140 / 150) - moneyWidth / 2;
  const moneyEndX = receiverX + figureWidth * (10 / 150) - moneyWidth / 2;

  // Figure Animations
  const giverRiseProgress = interpolate(
    frame,
    [fps * 0.5, fps * 2.0],
    [0, 1],
    { easing: Easing.out(Easing.exp), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const receiverRiseProgress = interpolate(
    frame,
    [fps * 0.7, fps * 2.2], // Staggered slightly
    [0, 1],
    { easing: Easing.out(Easing.exp), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const giverOpacity = interpolate(giverRiseProgress, [0, 0.2], [0, 1], { extrapolateRight: "clamp" });
  const receiverOpacity = interpolate(receiverRiseProgress, [0, 0.2], [0, 1], { extrapolateRight: "clamp" });

  // Generate sequence of money bills flowing across
  const billData = useMemo(() => {
    return Array.from({ length: 8 }).map((_, i) => {
      const start = fps * 2.5 + i * (fps * 0.25);
      const end = start + fps * 1.5;
      const arcJitter = (random(`arc-${i}`) - 0.5) * height * 0.05;
      const rotJitter = (random(`rot-${i}`) - 0.5) * 60;
      return { id: i, start, end, arcJitter, rotJitter };
    });
  }, [fps, height]);

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, transition: "none" }}>
      {/* Solid Background Color */}
      <AbsoluteFill
        style={{
          backgroundColor: solidBackgroundColor,
          transition: "none",
        }}
      />

      {/* Cinematic Scale Wrapper */}
      <AbsoluteFill style={{ transform: `scale(${cinematicScale})`, transformOrigin: "center center", transition: "none" }}>
        
        {/* Money Layer (renders behind the arms for a natural toss/catch depth illusion) */}
        <AbsoluteFill style={{ zIndex: 5, transition: "none" }}>
          {billData.map((bill) => {
            const progress = interpolate(frame, [bill.start, bill.end], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const isVisible = progress > 0 && progress < 1;
            
            // Fade in and out sharply
            const opacity = interpolate(frame, [bill.start, bill.start + 5, bill.end - 5, bill.end], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

            const x = interpolate(progress, [0, 1], [moneyStartX, moneyEndX]);
            // Slightly higher arc base to span the wider 16:9 frame naturally
            const arcHeight = (height * 0.22) + bill.arcJitter;
            const yOffset = Math.sin(progress * Math.PI) * arcHeight;
            const bottom = moneyBaseBottom + yOffset;
            const rotation = interpolate(progress, [0, 1], [-20 + bill.rotJitter, 20 + bill.rotJitter]);

            if (!isVisible) return null;

            return (
              <div
                key={bill.id}
                style={{
                  position: "absolute",
                  left: `${x}px`,
                  bottom: `${bottom}px`,
                  width: `${moneyWidth}px`,
                  height: `${moneyHeight}px`,
                  opacity,
                  transform: `rotate(${rotation}deg)`,
                  transition: "none",
                  willChange: "transform, opacity",
                }}
              >
                {/* Premium Abstract Bill / Chip SVG */}
                <svg
                  viewBox="0 0 100 60"
                  style={{
                    width: "100%",
                    height: "100%",
                    display: "block",
                    filter: `drop-shadow(0px 4px 12px ${moneyColor}80)`,
                  }}
                >
                  <rect x="0" y="0" width="100" height="60" rx="8" fill={moneyColor} />
                  <rect x="10" y="10" width="80" height="40" rx="4" fill="#000000" opacity="0.15" />
                  <circle cx="50" cy="30" r="12" fill="#000000" opacity="0.2" />
                  <path d="M 30 30 L 70 30" stroke="#000000" strokeWidth="4" strokeLinecap="round" opacity="0.15" />
                </svg>
              </div>
            );
          })}
        </AbsoluteFill>

        {/* Shadow Figures Layer */}
        <AbsoluteFill style={{ zIndex: 10, transition: "none" }}>
          
          {/* Giver (Left) */}
          <div
            style={{
              position: "absolute",
              left: `${giverX}px`,
              bottom: `${bottomOffset}px`,
              width: `${figureWidth}px`,
              height: `${figureHeight}px`,
              color: shadowColor,
              opacity: giverOpacity,
              transform: `translateY(${(1 - giverRiseProgress) * (figureHeight + 300)}px)`,
              transformOrigin: "bottom center",
              filter: "blur(1px)",
              transition: "none",
              willChange: "transform",
            }}
          >
            <svg viewBox="0 0 150 200" style={{ width: "100%", height: "100%", overflow: "visible", display: "block" }}>
              <circle cx="50" cy="40" r="22" fill="currentColor" />
              <path
                d="M 5 200
                   C 5 120 25 85 50 85
                   C 65 85 75 90 80 95
                   L 145 105
                   C 150 106 150 114 145 115
                   L 80 125
                   L 70 200 Z"
                fill="currentColor"
              />
            </svg>
          </div>

          {/* Receiver (Right) */}
          <div
            style={{
              position: "absolute",
              left: `${receiverX}px`,
              bottom: `${bottomOffset}px`,
              width: `${figureWidth}px`,
              height: `${figureHeight}px`,
              color: shadowColor,
              opacity: receiverOpacity,
              transform: `translateY(${(1 - receiverRiseProgress) * (figureHeight + 300)}px) scaleX(-1)`,
              transformOrigin: "bottom center",
              filter: "blur(1px)",
              transition: "none",
              willChange: "transform",
            }}
          >
            <svg viewBox="0 0 150 200" style={{ width: "100%", height: "100%", overflow: "visible", display: "block" }}>
              <circle cx="50" cy="40" r="22" fill="currentColor" />
              <path
                d="M 5 200
                   C 5 120 25 85 50 85
                   C 65 85 75 90 80 95
                   L 145 105
                   C 150 106 150 114 145 115
                   L 80 125
                   L 70 200 Z"
                fill="currentColor"
              />
            </svg>
          </div>

        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CinematicShadows;